/*
 * P46 checks: the accent derivation and how the prototype applies it.
 *
 *   node accent.test.js            # unit checks + browser checks; fails if the vectors file is out of date
 *   node accent.test.js --write    # regenerate docs/platform/p46-accent-vectors.json (the server's test vectors)
 *
 * Unit: every preset and 5,000 random colours pass all six contrast rules after derivation.
 * Browser: a custom colour sets --primary/--ring/--curtain in both themes, and the next load (sign-in)
 * paints the last accent before the app starts.
 */
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const L = require('./layout');
const SRC = fs.readFileSync(path.join(L.SRC, 'parts_helpers.js'), 'utf8');
const core = SRC.slice(SRC.indexOf('const ACCENTS = {'), SRC.indexOf('/* ACCENT-CORE-END */'));
const A = new Function(core + ';return { ACCENTS, deriveAccent, accentChecks, accToHex };')();
const VEC = path.join(L.ROOT, 'docs/platform/p46-accent-vectors.json');
let failed = 0; const fail = (m) => { failed++; console.log('FAIL', m); };

// ---- unit
for (const k of Object.keys(A.ACCENTS)) A.accentChecks(A.deriveAccent(k)).filter(c => !c.pass).forEach(c => fail(`preset ${k} ${c.theme} ${c.what} ${c.ratio}`));
let seed = 42; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const random = Array.from({ length: 5000 }, () => '#' + Math.floor(rnd() * 0xffffff).toString(16).padStart(6, '0'));
let adjusted = 0;
for (const hex of random) { const t = A.deriveAccent(hex); if (t.adjusted) adjusted++; A.accentChecks(t).filter(c => !c.pass).forEach(c => fail(`${hex} ${c.theme} ${c.what} ${c.ratio}`)); }
for (const bad of ['', 'teal2', '#12345', '#gggggg', 'rgb(0,0,0)', null]) if (A.deriveAccent(bad)) fail('accepted ' + bad);
console.log(`unit: 6 presets, ${random.length} random colours (${adjusted} adjusted), all rules pass: ${failed === 0}`);

// ---- vectors (the API ports deriveAccent and must reproduce these exactly)
const sample = [...Object.keys(A.ACCENTS), '#000000', '#ffffff', '#ffd400', '#00ff00', '#0000ff', '#808080', '#166445', '#e11d48', ...random.slice(0, 40)];
const vectors = { note: 'P46 test vectors: input -> derived tokens. Generated by tools/prototype-shots/accent.test.js --write from prototype/src/parts_helpers.js.', rules: { text: 4.5, ui: 3, curtain: 6 }, cases: sample.map(v => ({ input: v, tokens: A.deriveAccent(v) })) };
const json = JSON.stringify(vectors, null, 2) + '\n';
if (process.argv.includes('--write')) { fs.writeFileSync(VEC, json); console.log('wrote', path.relative(process.cwd(), VEC)); }
else if (!fs.existsSync(VEC) || fs.readFileSync(VEC, 'utf8') !== json) fail('docs/platform/p46-accent-vectors.json is out of date: run node accent.test.js --write');

// ---- browser
const HTML = fs.readFileSync(L.HTML, 'utf8');
const CSS = fs.readFileSync(path.resolve(__dirname, '.tw.css'), 'utf8');
async function page(ctx, route, noApp) {
  const p = await ctx.newPage(); const errs = []; p.on('pageerror', e => errs.push(e.message));
  await ctx.route('**/*', r => {
    const u = r.request().url();
    if (u.includes('cdn.tailwindcss.com')) return r.fulfill({ body: 'window.tailwind={};', contentType: 'text/javascript' });
    if (u.includes('vue.global')) return noApp ? r.abort() : r.fulfill({ path: require.resolve('vue/dist/vue.global.prod.js') });
    if (u.includes('lucide')) return r.fulfill({ path: require.resolve('lucide/dist/umd/lucide.min.js') });
    if (u.startsWith('http://proto/')) return r.fulfill({ contentType: 'text/html', body: '<!doctype html><html><head><meta charset=utf-8><style>' + CSS + '</style></head><body><script>window.__INIT_ROUTE=' + JSON.stringify(u.split('#')[1] || route) + '</script>' + HTML + '</body></html>' });
    return r.abort();
  });
  return { p, errs };
}
const prop = (p, n) => p.evaluate(n => getComputedStyle(document.documentElement).getPropertyValue(n).trim(), n);
(async () => {
  const b = await chromium.launch();
  for (const scheme of ['light', 'dark']) {
    const ctx = await b.newContext({ colorScheme: scheme, viewport: { width: 1280, height: 900 }, reducedMotion: 'reduce' });
    const { p, errs } = await page(ctx, 'workspace');
    await p.goto('http://proto/#workspace'); await p.waitForTimeout(900);
    await p.click('main [aria-label="Custom colour"]'); await p.fill('#w-acc-hex', '#ffd400'); await p.waitForTimeout(300);
    const t = A.deriveAccent('#ffd400'), want = scheme === 'light' ? [t.l, t.cl] : [t.d, t.cd];
    const got = [await prop(p, '--primary'), await prop(p, '--curtain')];
    if (got.join('|') !== want.join('|')) fail(`${scheme}: --primary/--curtain ${got} != ${want}`);
    if (await prop(p, '--ring') !== want[0]) fail(`${scheme}: --ring does not follow`);
    if (!(await p.locator('main :text("Adjusted for readability")').count())) fail(`${scheme}: no adjusted notice for #ffd400`);
    // next load: the boot script paints the last accent before the app runs (app blocked, so only the server HTML shows)
    const { p: p0 } = await page(ctx, 'login', true);
    await p0.goto('http://proto/#login'); await p0.waitForTimeout(300);
    const boot = await prop(p0, '--curtain');
    if (boot !== want[1]) fail(`${scheme}: boot curtain ${boot} != ${want[1]}`);
    if (!(await p0.locator('#boot-curtain').count())) fail(`${scheme}: no boot curtain in the server HTML`);
    await p0.close();
    // sign-in keeps the last accent
    const { p: p2, errs: e2 } = await page(ctx, 'login');
    await p2.goto('http://proto/#login'); await p2.waitForTimeout(900);
    if (await prop(p2, '--primary') !== want[0]) fail(`${scheme}: sign-in primary is not the last accent`);
    [...errs, ...e2].forEach(e => fail(`${scheme}: page error ${e}`));
    await ctx.close();
  }
  // organisation switch: Kilima Wholesale is amber
  const ctx = await b.newContext({ colorScheme: 'light', viewport: { width: 1280, height: 900 }, reducedMotion: 'reduce' });
  const { p } = await page(ctx, 'dashboard'); await p.goto('http://proto/#dashboard'); await p.waitForTimeout(900);
  const first = await p.evaluate(() => G.org.accent);
  if (await prop(p, '--primary') !== A.deriveAccent(first).l) fail('first load is not the organisation accent');
  const other = await p.evaluate(() => (G.orgs.find(o => o !== G.org && o.accent !== G.org.accent && !o.disabled) || {}).id);
  if (other) {   // organisation switch applies that organisation's accent (kit demo: Kilima Wholesale, amber)
    await p.evaluate(id => G.switchOrg(id), other); await p.waitForTimeout(2200);
    const acc = await p.evaluate(() => G.org.accent);
    if (await prop(p, '--primary') !== A.deriveAccent(acc).l) fail('switching organisation did not apply its accent');
  }
  await ctx.close();
  await b.close();
  console.log(failed ? `${failed} failed` : 'browser: custom accent applies in both themes; sign-in paints the last accent; first load and org switch apply each organisation\'s own accent, ok');
  process.exit(failed ? 1 : 0);
})();
